Source code in <code>effector/proposers.py</code> <pre><code>def propose(self, ctx: SearchContext, foc: int) -&gt; list:
    col = ctx.data[:, foc]
    candidates, seen = [], set()
    for k in range(2, self.max_children + 1):
        edges = np.unique(np.quantile(col, np.arange(1, k) / k))
        edges = tuple(float(e) for e in edges if col.min() &lt; e)
        if not edges or edges in seen:
            continue
        seen.add(edges)
        bounds = [-np.inf, *edges, np.inf]
        candidates.append(
            CandidateSplit(
                tuple(
                    Condition(foc, Interval(lo=lo, hi=hi))
                    for lo, hi in zip(bounds[:-1], bounds[1:])
                )
            )
        )
    return candidates
